      "activity_name": "U1 - Benchmark Design",
      "activity_description": "Design benchmark approach, metrics, and harness for comparing Sqoop vs jdbchdfs.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Benchmark Implementation",
      "activity_description": "Implement the benchmark tool/script and integrate into the project.",
      "most_likely_effort": 20
