      "most_likely_effort": 8
    },
    {
      "activity_id": "A23",
      "activity_name": "U8 - Rabbit Compression Design",
      "activity_description": "Design addition of compression property to Rabbit source and sink modules.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A24",
      "activity_name": "U8 - Rabbit Compression Implementation",
      "activity_description": "Modify Rabbit source and sink to support message compression (gzip/zip).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A25",
      "activity_name": "U8 - Rabbit Compression Testing and Documentation",
      "activity_description": "Write tests and update rabbit module documentation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A26",
      "activity_name": "Integration and System Testing",
      "activity_description": "Test all features together, ensure no regressions and that they work in combination.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A27",
      "activity_name": "Code Review and Refactoring",
