      "most_likely_effort": 8
    },
    {
      "activity_id": "A28",
      "activity_name": "Final Documentation and Release Preparation",
      "activity_description": "Update overall project documentation, release notes, and prepare for release.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 233
  }
}

